import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import { PlantResponse } from '@/interface/plant-response';

@Injectable()
export class PlantHierarchyApi {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly daprConfigService: DaprConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async fetchAllPlants(): Promise<Array<PlantResponse>> {
    const serviceAppId = this.daprConfigService.bindingplantHierarchy;
    const serviceMethodSeqnum = `plant/Plants`;

    const context: JobsLogContext = {
      method: 'fetchAllPlants',
      service: 'PlantHierarchyApi',
    };

    try {
      const options =
        process.env.TOKEN === ''
          ? {}
          : { headers: { authorization: `Bearer ${process.env.TOKEN}` } };
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethodSeqnum,
        HttpMethod.GET,
        undefined,
        options,
      );

      if (response) {
        return response as Array<PlantResponse>;
      }
      throw new Error('Invalid response from fetchAllPlants');
    } catch (error) {
      this.customLogger.error(
        `Error fetching all plants: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

