import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '../logger/app-logger';

interface LogTrace {
  details?: Record<string, unknown>;
  logType: string;
  operationName: string;
  runtime: number;
  srcLocation: string;
}

/**
 * Execution function and log runtime
 * @param customLogger Custom application logger
 * @param enabled Appilication config execLog permission
 * @param operation Function to execute
 * @param operationInfo Function properties
 * @param operationInfo.name Function name
 * @param operationInfo.srcLocation Caller code source location
 * @param details (optional)
 * @param startTime starting time
 * @returns function output
 */
export async function execAndLog<T>(
  customLogger: AppLogger,
  enabled: boolean,
  operation: () => Promise<T>,
  operationInfo: {
    name: string;
    srcLocation: string;
  },
  details?: Record<string, unknown>,
  startTime = Date.now(),
): Promise<T> {
  const result = await operation();
  if (enabled) {
    const context: JobsLogContext = {
      method: operationInfo.name,
      service: 'ExecAndLogService',
    };

    const logTrace: LogTrace = {
      details,
      logType: 'Exec trace',
      operationName: operationInfo.name,
      runtime: Date.now() - startTime,
      srcLocation: operationInfo.srcLocation,
    };
    customLogger.debug(JSON.stringify(logTrace), context);
  }
  return result;
}

/**
 * Calculate and compare date
 * @param taskPublishTime Task publish time from the record
 * @param ttl The time-to-live (TTL) from the configuration.
 * @returns return a boolean value comparing the duration of the publish with date now
 */
export function isExpiredState(taskPublishTime: string, ttl: number): boolean {
  const taskPublishMillis = new Date(taskPublishTime).getTime();
  return taskPublishMillis + ttl * 1000 < Date.now();
}

