import { DaprClient } from '@dapr/dapr';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { TaskMessage } from '@/interface/task-message.interface';

@Injectable()
export class PublishMessageService {
  private readonly eventhubService: EventhubService;

  public constructor(
    eventhubService: EventhubService,
    private readonly customLogger: AppLogger,
  ) {
    this.eventhubService = eventhubService;
  }

  public async publishMessage(topic: string, data: TaskMessage): Promise<void> {
    const context: JobsLogContext = {
      method: 'publishMessage',
      object: topic,
      service: 'PublishMessageService',
    };

    try {
      const daprClient = new DaprClient();
      const { pubSubName } = this.eventhubService;
      const options = {
        metadata: { partitionKey: String(data.plant) },
      };
      await daprClient.pubsub.publish(pubSubName, topic, data, options);
    } catch (error) {
      this.customLogger.error(
        `Failed to publish: ${error.message},${JSON.stringify(data)}`,
        context,
        error.stack,
      );
    }
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class AppConfigInitialConfigService implements OnModuleInit {
  public constructor(private readonly configService: ConfigService) {}

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  public get appConfigCachingTtl(): number {
    return this.configService.get<number>('appConfigCachingTtl') ?? 20_000;
  }

  public get appConfigEndpoint(): string {
    return this.configService.get<string>('appConfigEndpoint') ?? '';
  }

  public get appConfigforceinitPropertyName(): string {
    return (
      this.configService.get<string>('appConfigforceinitPropertyName') ?? ''
    );
  }

  public get appConfigMetricsEnabledPropertyName(): string {
    return (
      this.configService.get<string>('appConfigMetricsEnabledPropertyName') ??
      ''
    );
  }

  public get appConfigExecLogEnabledPropertyName(): string {
    return (
      this.configService.get<string>('appConfigExecLogEnabledPropertyName') ??
      ''
    );
  }

  public get appConfigLogLevelPropertyName(): string {
    return (
      this.configService.get<string>('appConfigLogLevelPropertyName') ?? ''
    );
  }

  private checkConfiguration(): void {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'AppConfigInitialConfigService',
    };
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      { key: 'appConfigEndpoint', value: this.appConfigEndpoint },
      {
        key: 'appConfigExecLogEnabledPropertyName',
        value: this.appConfigExecLogEnabledPropertyName,
      },
      {
        key: 'appConfigMetricsEnabledPropertyName',
        value: this.appConfigMetricsEnabledPropertyName,
      },
      {
        key: 'propertyNameLogLevel',
        value: this.appConfigLogLevelPropertyName,
      },
      {
        key: 'appConfigforceinitPropertyName',
        value: this.appConfigforceinitPropertyName,
      },
    ];

    /*
     * Check mandatory fields
     */
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        Logger.error(`Missing configuration value for ${config.key}`, context);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
  }
}

