import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class OrchestratorConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public async mvOrchestratorDelayMilliseconds(): Promise<number> {
    const value = this.configService.get<number>(
      'mvOrchestratorDelayMilliseconds',
    );

    if (value === undefined) {
      const appStoreValue = await this.appConfigService.getConfigurationValue(
        this.mvOrchestratorDelayMillisecondsPropertyName,
      );

      const delay = Number(appStoreValue);
      return Number.isNaN(delay) ? 100 : delay;
    }
    return value;
  }

  public get mvOrchestratorDelayMillisecondsPropertyName(): string {
    return (
      this.configService.get<string>(
        'mvOrchestratorDelayMillisecondsPropertyName',
      ) ?? ''
    );
  }

  public onModuleInit(): void {
    this.checkConfiguration();
  }

  private checkConfiguration(): void {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'OrchestratorConfigService',
    };

    // List of required configurations
    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      {
        key: 'mvOrchestratorDelayMillisecondsPropertyName',
        value: this.mvOrchestratorDelayMillisecondsPropertyName,
      },
    ];

    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
  }
}

