import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { Interval } from '@nestjs/schedule';
import { Mutex } from 'async-mutex';
import { RedisService } from 'src/redis/redis.service';
import { v4 as uuidv4 } from 'uuid';
import { PlantHierarchyApi } from '@/common/api/plant-hierarchy-api';
import { dictionaryState } from '@/common/constants/dictionary-state';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { isExpiredState } from '@/common/helpers/date/convert-date';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { ObservabilityConfigService } from '@/config/observability-config/observability-config.service';
import { OrchestratorConfigService } from '@/config/orchestrator/orchestrator.service';
import { RedisConfigService } from '@/config/redis/redis-store.service';
import { Dictionary } from '@/interface/dictionary.interface';
import { TaskMessage } from '@/interface/task-message.interface';

@Injectable()
export class OrchestratorService {
  private readonly plants: Array<number> = [];

  private readonly plantMutex = new Mutex();

  private lastSnaphotTimestamp = Date.now();

  /**
   * Snapshot interval in ms
   */
  private readonly snapshotInterval = 1000;

  public constructor(
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
    private readonly redisService: RedisService,
    private readonly plantHYRApi: PlantHierarchyApi,
    private readonly redisStoreService: RedisConfigService,
    private readonly observabilityConfigService: ObservabilityConfigService,
    private readonly mutexManagerService: MutexManagerService,
    private readonly orchestratorConfigService: OrchestratorConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Resynchronize in memory plant
   * from Service
   */
  private async synchronizeInMemoryPlants(): Promise<void> {
    const plantMutexRelease = await this.plantMutex.acquire();

    const plantsHYRApi = await this.plantHYRApi.fetchAllPlants();
    const context: JobsLogContext = {
      method: 'synchronizeInMemoryPlants',
      service: 'OrchestratorService',
    };

    const plantsToAdd = plantsHYRApi
      .map((m) => m.plantId)
      .filter((p) => !this.plants.includes(p));
    this.customLogger.debug(
      `synchronizeInMemoryPlants - plantsToAdd =${JSON.stringify(plantsToAdd)}`,
      context,
    );
    const forceInitEnabled = await this.observabilityConfigService.forceInit();
    const allRedisKeys = await this.redisService.getAllKeys();
    const isRedisEmpty = !allRedisKeys || allRedisKeys.length === 0;
    const promises = plantsToAdd.map(async (plant) => {
      let release;
      try {
        release = await this.mutexManagerService.getMutex(plant).acquire();
        const existingData = await this.redisService.read(plant.toString());
        if (
          forceInitEnabled === false &&
          ((existingData?.state && existingData.state !== '') || !isRedisEmpty)
        ) {
          return;
        }

        const details: Dictionary = {
          state: 'init',
          taskPublishTime: '',
          updateDuration: 0,
          updateTime: '',
        };
        await this.redisService.write(plant.toString(), details);
      } catch (error) {
        this.customLogger.error(
          `Plant ${plant} - Error during Redis update in ${error.message ?? error.stack}`,
          context,
        );
      } finally {
        if (release) release();
      }
    });

    try {
      await Promise.allSettled(promises);
      this.plants.push(...plantsToAdd);
      this.redisService.saveKeysInRedis(this.plants);
    } catch (error) {
      this.customLogger.error(
        `synchronizeInMemoryPlants - Error =${error.message}`,
        context,
        error.stack,
      );
    } finally {
      if (plantMutexRelease) plantMutexRelease();
    }
  }

  /**
   * Processing for a given plant
   * @param plantKey - plant code
   */
  private async processPlant(plantKey: number): Promise<void> {
    const logOperationInfo = {
      name: '',
      srcLocation: 'processPlant',
    };
    const logOperationDetails = {
      plantKey,
    };
    const execLogEnabled =
      await this.observabilityConfigService.execlogEnabled();
    const ttl = Number(this.redisStoreService.ttlStore);
    logOperationInfo.name = 'Redis read';
    const data = await execAndLog(
      this.customLogger,
      execLogEnabled,
      () => this.redisService.read(plantKey.toString()),
      logOperationInfo,
      logOperationDetails,
    );
    if (
      [dictionaryState.init, dictionaryState.expired]
        .map((m) => m.toUpperCase())
        .includes(data.state.toUpperCase())
    ) {
      data.state = dictionaryState.updating;
      data.taskPublishTime = new Date().toISOString();
      const message: TaskMessage = {
        plant: plantKey,
        publishTime: data.taskPublishTime,
        ttl,
        updateDuration: data.updateDuration,
        updateTime: data.updateTime,
        uuid: uuidv4(),
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicTasks,
        message,
      );
    } else {
      const isExpiredStatus = isExpiredState(data.taskPublishTime, ttl);
      if (!isExpiredStatus) return;
      data.state = dictionaryState.expired;
    }

    logOperationInfo.name = 'Redis write';
    await execAndLog(
      this.customLogger,
      execLogEnabled,
      () => this.redisService.write(plantKey.toString(), data),
      logOperationInfo,
      logOperationDetails,
    );
  }

  @Interval(10_000)
  public async schedulerInterval(): Promise<void> {
    if (this.plants.length === 0) {
      await this.synchronizeInMemoryPlants();
    }

    const existPlants = await this.redisService.getAllKeys();
    if (existPlants.length > this.plants.length) {
      const plantsToAdd = existPlants
        .map(Number)
        .filter((p) => !this.plants.includes(p));
      this.plants.push(...plantsToAdd);
    }

    const processorPromises = this.plants.map(async (p) => {
      let release;
      try {
        release = await this.mutexManagerService.getMutex(p).acquire();
        await this.processPlant(p);
      } catch (error) {
        const context: JobsLogContext = {
          method: 'schedulerInterval',
          plant: p,
          service: 'OrchestratorService',
        };

        this.customLogger.error(
          `Error during processPlant ${p} - ${error.message}`,
          context,
          error.stack,
        );
      } finally {
        if (release) release();
      }
    });

    // Run all tasks concurrently
    await Promise.allSettled(processorPromises);
  }

  private async logDictionnarySnapshot(): Promise<void> {
    const promises = this.plants.map(async (plant) => {
      let release;
      try {
        release = await this.mutexManagerService.getMutex(plant).acquire();
        const plantDict = await this.redisService.read(plant.toString());

        const context: JobsLogContext = {
          method: 'logDictionnarySnapshot',
          plant,
          service: 'OrchestratorService',
        };

        this.customLogger.debug(
          `Plant ${plant} - Dictionnary snapshot: ${JSON.stringify(plantDict)}`,
          context,
        );
      } finally {
        if (release) release();
      }
    });
    await Promise.allSettled(promises);
  }

  public async startOrchestrator(): Promise<void> {
    try {
      await this.schedulerInterval();
      if (Date.now() > this.lastSnaphotTimestamp + this.snapshotInterval) {
        this.lastSnaphotTimestamp = Date.now();
        await this.logDictionnarySnapshot();
      }
    } catch (error) {
      const context: JobsLogContext = {
        method: 'startOrchestrator',
        service: 'OrchestratorService',
      };

      this.customLogger.error(
        `Error schedulerInterval ${error.message ?? error.stack}`,
        context,
      );
    }

    const orchestratorDelay =
      await this.orchestratorConfigService.mvOrchestratorDelayMilliseconds();

    setTimeout(() => this.startOrchestrator(), orchestratorDelay);
  }
}

