import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisConfigService } from '@/config/redis/redis-store.service';
import { Dictionary } from '@/interface/dictionary.interface';

@Injectable()
export class RedisService {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  /*  Private async migrationPhase(): Promise<boolean> {
    return this.redisConfigService.migrationPhase();
  } */

  /**
   * Get the old and new Redis store names.
   * @returns An object containing:
   *   - `newStore`: the new Redis store name
   */ private getStores(): {
    newStore: string;
    newRedisPlant: string;
  } {
    return {
      newStore: this.redisConfigService.redisStoreAmr,
      newRedisPlant: this.redisConfigService.redisPlantAmr,
    };
  }

  public async read(key: string): Promise<Dictionary> {
    const context: JobsLogContext = {
      method: 'read',
      object: key,
      service: 'RedisService',
    };

    try {
      const { newStore } = this.getStores();

      const result = await this.daprClient.state.get(newStore, key);

      let dictionaryResult: Dictionary = {
        state: '',
        taskPublishTime: '',
        updateDuration: 0,
        updateTime: '',
      };

      if (Object.values(result.valueOf()).length > 0) {
        // Attempt to parse the result if it's a string
        dictionaryResult =
          typeof result === 'string'
            ? (JSON.parse(result) as Dictionary)
            : (result as Dictionary);
      }
      return dictionaryResult;
    } catch (error) {
      this.customLogger.error(
        `Error reading from Redis with mutex for key ${key}: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Write a key-value pair to Redis based on the migration phase.
   *
   * - If migrationPhase is true, the value is written to both the old and new stores (if they exist).
   * - If migrationPhase is false, the value is written only to the new store.
   * @param key - The key to write to Redis.
   * @param value - The value to associate with the key. Must conform to the Dictionary interface.
   * @returns A Promise that resolves when the value has been successfully saved.
   * @throws Throws an error if the write operation fails.
   */
  public async write(key: string, value: Dictionary): Promise<void> {
    const context: JobsLogContext = {
      method: 'write',
      object: key,
      service: 'RedisService',
    };

    try {
      const { newStore } = this.getStores();

      await this.daprClient.state.save(newStore, [{ key, value }]);
    } catch (error) {
      this.customLogger.error(
        `Redis write for plant ${key} - Error writing to Redis with mutex: ${key} ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Get all keys from the appropriate Redis store based on the migration phase.
   *
   * - If migrationPhase is true, reads from the old store first; falls back to the new store if the old store is empty.
   * - If migrationPhase is false, reads from the new store only.
   * @returns A Promise that resolves to an array of strings representing all keys stored in Redis.
   *          Returns an empty array if no keys are found or if an error occurs.
   */
  public async getAllKeys(): Promise<Array<string>> {
    const context: JobsLogContext = {
      method: 'getAllKeys',
      service: 'RedisService',
    };

    try {
      const { newRedisPlant } = this.getStores();
      const store = newRedisPlant;

      if (!store) return [];

      const result = await this.daprClient.state.get(store, 'KEYS');
      return Array.isArray(result) ? result : [];
    } catch {
      this.customLogger.error(
        'Error fetching keys from Dapr state store:',
        context,
      );
      return [];
    }
  }

  public async saveKeysInRedis(keyplant: Array<number>): Promise<void> {
    const context: JobsLogContext = {
      method: 'saveKeysInRedis',
      service: 'RedisService',
    };

    try {
      const { newRedisPlant } = this.getStores();

      const existingKeys = await this.getAllKeys();
      const mergedKeys = [
        ...new Set([...existingKeys, ...keyplant.map(String)]),
      ];
      await this.daprClient.state.save(newRedisPlant, [
        { key: 'KEYS', value: mergedKeys },
      ]);
    } catch (error) {
      this.customLogger.error(
        `saveKeysInRedis with mutex for plant ${keyplant} - Error writing to Redis with mutex: ${keyplant} ${error.message ?? error.stack}`,
        context,
      );
      throw error;
    }
  }
}

import { Controller, Get, Post, Req } from '@nestjs/common';
import { Request } from 'express';
import { SubscribeMessageService } from './subscribe.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';

interface SubscribeMetaDataDto {
  pubsubname: string;
  route: string;
  topic: string;
  metadata?: Record<string, string>;
}

const topics = {
  topicContainer: process.env.TOPIC_CONTAINER,
  topicLauncherKpiUpdates: process.env.LANCHER_KPI_UPDATES,
  topicOutbound: process.env.TOPIC_OUTBOUND,
  topicPlants: process.env.TOPIC_PLANTS,
  topicResult: process.env.TOPIC_RESULTS,
  topicTpaAssignement: process.env.TOPIC_TPA_ASSIGNEMENT,
  topicTransfer: process.env.TOPIC_TRANSFER,
  topicWorkcenterUpdates: process.env.WORKCENTER_UPDATES,
};

@Controller()
export class SubscribeController {
  public constructor(
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  @Get('/dapr/subscribe')
  public async subscribeMetaData(): Promise<Array<SubscribeMetaDataDto>> {
    const subscriptions: Array<SubscribeMetaDataDto> = [];

    if (this.eventhubService.topicResult) {
      const checkpointFrequency =
        await this.eventhubService.checkPointFrequencyResult();
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicResult}`,
        topic: this.eventhubService.topicResult,
        metadata: {
          checkPointFrequencyPerPartition: checkpointFrequency,
        },
      });
    }

    if (this.eventhubService.topicPlants) {
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicPlants}`,
        topic: this.eventhubService.topicPlants,
      });
    }
    if (this.eventhubService.topicOutbound) {
      const checkpointFrequency =
        await this.eventhubService.checkPointFrequencyOutbound();
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicOutbound}`,
        topic: this.eventhubService.topicOutbound,
        metadata: {
          checkPointFrequencyPerPartition: checkpointFrequency,
        },
      });
    }

    if (this.eventhubService.topicTpaAssignement) {
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicTpaAssignement}`,
        topic: this.eventhubService.topicTpaAssignement,
      });
    }

    if (this.eventhubService.topicContainer) {
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicContainer}`,
        topic: this.eventhubService.topicContainer,
      });
    }

    if (this.eventhubService.topicTransfer) {
      const checkpointFrequency =
        await this.eventhubService.checkPointFrequencyTransfer();
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicTransfer}`,
        topic: this.eventhubService.topicTransfer,
        metadata: {
          checkPointFrequencyPerPartition: checkpointFrequency,
        },
      });
    }

    if (this.eventhubService.topicLauncherKpiUpdates) {
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicLauncherKpiUpdates}`,
        topic: this.eventhubService.topicLauncherKpiUpdates,
      });
    }

    if (this.eventhubService.topicWorkcenterUpdates) {
      subscriptions.push({
        pubsubname: this.eventhubService.pubSubName,
        route: `/${this.eventhubService.topicWorkcenterUpdates}`,
        topic: this.eventhubService.topicWorkcenterUpdates,
      });
    }

    return subscriptions;
  }

  @Post(`/${topics.topicResult || 'topic-result'}`)
  public async receiveResult(@Req() request: Request): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessage(data);
    return 'OK';
  }

  @Post(`/${topics.topicPlants || 'topic-plants'}`)
  public async receivePlants(): Promise<string> {
    await this.subscribeMessageService.handlePlantMessage();
    return 'OK';
  }

  @Post(`/${topics.topicOutbound || 'topic-outbound'}`)
  public async receiveOutbound(@Req() request: Request): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageOutbound(data);
    return 'OK';
  }

  @Post(`/${topics.topicTpaAssignement || 'topic-tpa-assignement'}`)
  public async receiveTpaAssignement(@Req() request: Request): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageTpaAssignement(data);
    return 'OK';
  }

  @Post(`/${topics.topicContainer || 'topic-container'}`)
  public async receiveContainer(@Req() request: Request): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageContainer(data);
    return 'OK';
  }

  @Post(`/${topics.topicTransfer || 'topic-transfer'}`)
  public async receiveTransfer(@Req() request: Request): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageTransfer(data);
    return 'OK';
  }

  @Post(`/${topics.topicLauncherKpiUpdates || 'topic-launcher-kpi-updates'}`)
  public async receiveLauncherKpiUpdates(
    @Req() request: Request,
  ): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageLauncherKpiUpdates(data);
    return 'OK';
  }

  @Post(`/${topics.topicWorkcenterUpdates || 'topic-workcenter-updates'}`)
  public async receiveWorkcenterUpdates(
    @Req() request: Request,
  ): Promise<string> {
    const { data } = request.body;
    await this.subscribeMessageService.handleMessageWorkcenterUpdates(data);
    return 'OK';
  }
}

