import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { v4 as uuidv4 } from 'uuid';
import { PlantHierarchyApi } from '@/common/api/plant-hierarchy-api';
import { dictionaryState } from '@/common/constants/dictionary-state';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { ObservabilityConfigService } from '@/config/observability-config/observability-config.service';
import { OrchestratorConfigService } from '@/config/orchestrator/orchestrator.service';
import { RedisConfigService } from '@/config/redis/redis-store.service';
import { ResultMessageDto } from '@/dtos/result-message-dto';
import { ContainerMessage } from '@/interface/container-message';
import { Dictionary } from '@/interface/dictionary.interface';
import { LauncherKpiUpdatesMessage } from '@/interface/launcher-kpi-updates';
import { OutboundMessage } from '@/interface/outbound-message';
import { TaskMessage } from '@/interface/task-message.interface';
import { TpaAssignementMessage } from '@/interface/tpa-assignement';
import { TransferMessage } from '@/interface/transfer-message';
import { WorkcenterUpdatesMessage } from '@/interface/workcenter-updates';
import { OrchestratorService } from '@/orchestrator/orchestrator.service';
import { RedisService } from '@/redis/redis.service';

@Injectable()
export class SubscribeMessageService implements OnModuleInit {
  public constructor(
    private readonly plantHYRApi: PlantHierarchyApi,
    private readonly eventhubService: EventhubService,
    private readonly redisService: RedisService,
    private readonly publishMessageService: PublishMessageService,
    private readonly redisStoreService: RedisConfigService,
    private readonly observabilityConfigService: ObservabilityConfigService,
    private readonly mutexManagerService: MutexManagerService,
    private readonly orchestratorConfigService: OrchestratorConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  private async handleMessageCommon(
    message:
      | OutboundMessage
      | TpaAssignementMessage
      | ContainerMessage
      | TransferMessage
      | WorkcenterUpdatesMessage
      | LauncherKpiUpdatesMessage,
  ): Promise<Dictionary> {
    const logOperationInfo = {
      name: 'readForhandleMessageCommon',
      srcLocation: 'handleMessageCommon',
    };
    const logOperationDetails = {
      plant: message.plant,
    };
    const execLogEnabled =
      await this.observabilityConfigService.execlogEnabled();
    const data = await execAndLog(
      this.customLogger,
      execLogEnabled,
      () => this.redisService.read(message.plant.toString()),
      logOperationInfo,
      logOperationDetails,
    );
    return data;
  }

  /**
   * /!\ ENSURE that updateDictionary is thread safe callsed
   * @param data ResultMessageDto
   */
  public async updateDictionary(data: ResultMessageDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'updateDictionary',
      plant: data.plant,
      service: 'SubscribeMessageService',
    };

    try {
      const plantKey = data.plant.toString();
      const result = await this.redisService.read(plantKey);
      if (result) {
        result.updateTime = String(data.updateTime);
        result.updateDuration = data.updateDuration;
        result.state = dictionaryState.updated;
      }
      this.customLogger.debug(
        `updateDictionary - Update dictionnary ${plantKey} : ${JSON.stringify(result)}`,
        context,
      );
      await this.redisService.write(plantKey, result);
    } catch (error) {
      this.customLogger.error(
        `plant ${data.plant} Error updating dictionary in Redis with mutex: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async handleMessage(message: ResultMessageDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessage',
      plant: message.plant,
      service: 'SubscribeMessageService',
    };

    let release;
    try {
      release = await this.mutexManagerService
        .getMutex(message.plant)
        .acquire();
      const ttl = Number(this.redisStoreService.ttlStore);
      const orchestratorPublishTimeInMillis = new Date(
        message.orchestratorPublishTime,
      ).getTime();

      if (!Number.isNaN(orchestratorPublishTimeInMillis)) {
        this.customLogger.debug(
          `Plant ${message.plant} - Processor response time ${JSON.stringify({
            reponseTime: Date.now() - orchestratorPublishTimeInMillis,
          })}`,
          context,
        );
      }

      // To identify old message that stayed in the hub
      // When there is a long restart from orchestrator
      if (
        Date.now() - orchestratorPublishTimeInMillis > ttl * 1000 &&
        message.updateDuration <= ttl
      ) {
        this.customLogger.debug(
          `Plant ${message.plant} - Obsolete msg detected orchestratorPublishTimeInMillis=${orchestratorPublishTimeInMillis},updateDuration=${message.updateDuration}, ttl=${ttl}`,
          context,
        );
        return;
      }

      await this.updateDictionary(message);
    } catch (error) {
      this.customLogger.error(
        `Plant ${message.plant} - Error processing results message: ${error.message ?? error.stack}`,
        context,
      );
    } finally {
      if (release) release();
    }
  }

  public async handlePlantMessage(): Promise<void> {
    const context: JobsLogContext = {
      method: 'handlePlantMessage',
      service: 'SubscribeMessageService',
    };

    try {
      const plants = await this.plantHYRApi.fetchAllPlants();
      const existPlants = await this.redisService.getAllKeys();

      const plantsToAdd = plants
        .map((m) => m.plantId)
        .filter((p) => !existPlants.includes(String(p)));
      if (plantsToAdd.length > 0) {
        const promises = [];
        for (const plantId of plantsToAdd) {
          const newDictionary: Dictionary = {
            state: 'init',
            taskPublishTime: '',
            updateDuration: 0,
            updateTime: '',
          };
          const plantkey = String(plantId);
          promises.push(this.redisService.write(plantkey, newDictionary));
        }
        await Promise.allSettled(promises);
        await this.redisService.saveKeysInRedis(plantsToAdd);
      }
    } catch (error) {
      this.customLogger.error(
        `Error processing message: ${error.message ?? error.stack}`,
        context,
      );
    }
  }

  public async handleMessageOutbound(message: OutboundMessage): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessageOutbound',
      plant: message.plant,
      service: 'SubscribeMessageService',
    };

    this.customLogger.debug(
      `Received OutboundMessage ${JSON.stringify(message)}`,
      context,
    );
    let release;
    try {
      release = await this.mutexManagerService
        .getMutex(message.plant)
        .acquire();
      const data = await this.handleMessageCommon(message);
      const ttl = Number(this.redisStoreService.ttlStore);
      const taskmessage: TaskMessage = {
        outbound: message.outbound,
        plant: message.plant,
        publishTime: new Date().toISOString(),
        ttl,
        updateDuration: data.updateDuration,
        updateTime: data.updateTime,
        uuid: uuidv4(),
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicTasks,
        taskmessage,
      );
    } catch (error) {
      this.customLogger.error(
        `Plant ${message.plant} - Error processing outbound message: ${error.message}`,
        context,
        error.stack,
      );
    } finally {
      if (release) release();
    }
  }

  public async handleMessageTpaAssignement(
    message: TpaAssignementMessage,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessageTpaAssignement',
      plant: message.plant,
      service: 'SubscribeMessageService',
    };

    this.customLogger.debug(
