    } catch (error) {
      this.customLogger.error(
        `Plant ${message.plant} - Error processing tpa assignement message: ${error.message}`,
        context,
        error.stack,
      );
    } finally {
      if (release) release();
    }
  }

  public async handleMessageWorkcenterUpdates(
