  public async handleMessageContainer(
    message: ContainerMessage,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessageContainer',
      plant: message.plant,
      service: 'SubscribeMessageService',
    };

    this.customLogger.debug(
      `Received ContainerMessage ${JSON.stringify(message)}`,
