    } finally {
      if (release) release();
    }
  }

  public onModuleInit(): void {
    const context: JobsLogContext = {
      method: 'onModuleInit',
      service: 'SubscribeMessageService',
    };

    try {
      // Using self scheduler because nestjs is running 2 schedulers in //
      new OrchestratorService(
        this.publishMessageService,
        this.eventhubService,
        this.redisService,
        this.plantHYRApi,
        this.redisStoreService,
        this.observabilityConfigService,
        this.mutexManagerService,
        this.orchestratorConfigService,
        this.customLogger,
      ).startOrchestrator();

      this.customLogger.debug('Orchestrator started successfully', context);
    } catch (error) {
      this.customLogger.error(
        `Error starting orchestrator: ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

